"""Lyrics for 'I Know an Old Lady Who Swallowed a Fly' (cumulative song)."""

_ANIMALS = ["fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"]

_COMMENTS = {
    1: None,
    2: "It wriggled and jiggled and tickled inside her.",
    3: "How absurd to swallow a bird!",
    4: "Imagine that, to swallow a cat!",
    5: "What a hog, to swallow a dog!",
    6: "Just opened her throat and swallowed a goat!",
    7: "I don't know how she swallowed a cow!",
    8: "She's dead, of course!",
}


def _refers_to(verse, animal):
    """How a lower animal is referred to when swallowed to catch it."""
    if verse == 2:
        return "the spider that wriggled and jiggled and tickled inside her"
    return f"the {animal}"


def _verse(verse):
    animal = _ANIMALS[verse - 1]
    lines = [f"I know an old lady who swallowed a {animal}."]
    comment = _COMMENTS[verse]
    if comment is not None:
        lines.append(comment)
    if verse == 8:
        return lines
    lines.append("I don't know why she swallowed the fly. Perhaps she'll die.")
    for caught in range(verse - 1, 0, -1):
        prev = _ANIMALS[caught - 1]
        lines.append(
            f"She swallowed the {prev} to catch {_refers_to(caught, _ANIMALS[caught - 1])}."
        )
    return lines


def recite(start_verse, end_verse):
    lines = []
    for verse in range(start_verse, end_verse + 1):
        if lines:
            lines.append("")
        lines.extend(_verse(verse))
    return lines

